-- =============================================================================
-- Spring 2025 historical season — standalone, idempotent loader.
--
-- Use this to add ONLY the Spring 2025 season to an already-seeded database
-- (e.g. staging). The main supabase/seed.sql is built for a fresh `db reset`
-- and would fail on duplicate seasons/teams/players if re-run against a
-- populated DB.
--
-- Safe to run more than once: every insert uses ON CONFLICT DO NOTHING and the
-- awards are cleared+reinserted. The whole thing runs in one transaction, so a
-- failure rolls back cleanly (no partial load).
--
-- This script is SELF-CONTAINED: it inserts every player the Spring 2025
-- rosters reference — the five debutants (Orr, Howe, Hull, Esposito, Dryden)
-- AND the returning players (Gretzky, Lemieux, Yzerman, …) — each with
-- ON CONFLICT (id) DO NOTHING. Players that already exist are left untouched
-- (no name overwrite); any missing ones are created. This makes the load work
-- even if staging's base seed is incomplete (e.g. missing Joe Melanson).
-- =============================================================================

begin;

-- ---------- season ----------
insert into seasons (id, season_type, year, name, start_date, end_date, is_current) values
  ('00000000-0000-0000-0000-000000000ccc', 'spring', 2025, 'Spring 2025', '2025-03-01', '2025-06-30', false)
on conflict do nothing;

-- ---------- teams (color-name convention) ----------
insert into teams (id, season_id, name, slug, color) values
  ('11000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000ccc', 'Red',   'red',   '#dc2626'),
  ('11000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000ccc', 'Blue',  'blue',  '#2563eb'),
  ('11000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000ccc', 'White', 'white', '#e5e7eb'),
  ('11000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000ccc', 'Black', 'black', '#1f2937')
on conflict do nothing;

